// wf-photo-upload — R15 sovereign photo WRITE path (2026-06-13).
// Writes ONE family/property photo to the NAS. Security (mirrors the read-
// bridge hardening): bearer auth is enforced by the webhook's headerAuth
// credential; this node re-validates dest + filename so nothing can escape
// the photo roots, caps the decoded size, and verifies the bytes are a real
// JPEG/PNG/WebP before writing. Returns { ok, id } or an error envelope.
const fs = require('fs');
const path = require('path');

const FAMILY_ROOT = '/data/family-photos';          // bind-mounted; see README
const PROPERTY_ROOT = '/data/property-photos';       // per-property subfolders
const SAFE = /^[A-Za-z0-9._-]{1,64}$/;
const MAX_BYTES = 8 * 1024 * 1024;                   // 8MB decoded ceiling

function fail(msg) { return [{ json: { ok: false, error: msg } }]; }

const body = ($input.first().json && ($input.first().json.body || $input.first().json)) || {};
const dest = String(body.dest || 'family');
let filename = String(body.filename || '');
const dataUrl = String(body.dataUrl || '');

if (dest !== 'family' && !SAFE.test(dest)) return fail('bad dest');
if (dest.includes('..') || dest.includes('/')) return fail('bad dest');

filename = filename.replace(/[^A-Za-z0-9._-]/g, '_').slice(0, 80);
if (!filename || filename.includes('..')) filename = 'photo-' + Date.now() + '.jpg';

const m = dataUrl.match(/^data:image\/(jpeg|jpg|png|webp);base64,([A-Za-z0-9+/=]+)$/);
if (!m) return fail('not an image data url');
const buf = Buffer.from(m[2], 'base64');
if (buf.length === 0 || buf.length > MAX_BYTES) return fail('empty or too large');

// Magic-byte check: JPEG FFD8, PNG 89504E47, WEBP 'RIFF'....'WEBP'.
const isJpeg = buf[0] === 0xFF && buf[1] === 0xD8;
const isPng = buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47;
const isWebp = buf.slice(0, 4).toString('ascii') === 'RIFF' && buf.slice(8, 12).toString('ascii') === 'WEBP';
if (!isJpeg && !isPng && !isWebp) return fail('bytes are not a supported image');

const dir = dest === 'family' ? FAMILY_ROOT : path.join(PROPERTY_ROOT, dest);
// Final guard: the resolved path must stay inside its root.
const root = dest === 'family' ? FAMILY_ROOT : PROPERTY_ROOT;
const full = path.join(dir, filename);
if (!path.resolve(full).startsWith(path.resolve(root))) return fail('path escape');

try {
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(full, buf);
} catch (e) {
  return fail('write failed: ' + (e && e.message ? e.message : 'io'));
}
return [{ json: { ok: true, id: filename, dest, bytes: buf.length } }];
